examples.setup:
CREATE TABLE accounts (id int PRIMARY KEY, balance int NOT NULL);
INSERT INTO accounts VALUES (1, 100), (2, 100);
CREATE TABLE sessions (name text PRIMARY KEY, pid int NOT NULL);

files.examples/01_blocking.sql:
-- LEARN(sql.security-ops.monitoring): when it's slow, first ask who is waiting, on what, and for whom.
A: INSERT INTO sessions VALUES ('A', pg_backend_pid());
B: INSERT INTO sessions VALUES ('B', pg_backend_pid());

-- A starts a transfer, then stalls before COMMIT (a slow HTTP call, say).
A: BEGIN;
A: UPDATE accounts SET balance = balance - 10 WHERE id = 1;
B: SELECT s.name, a.state, a.wait_event_type, a.wait_event, a.query
   FROM pg_stat_activity a JOIN sessions s USING (pid)
   WHERE s.name = 'A';

-- B wants the same row and has to wait.
B: UPDATE accounts SET balance = balance + 10 WHERE id = 1;
A: SELECT s.name, a.state, a.wait_event_type, a.wait_event,
          (SELECT array_agg(b.name) FROM sessions b
           WHERE b.pid = ANY (pg_blocking_pids(a.pid))) AS blocked_by
   FROM pg_stat_activity a JOIN sessions s USING (pid)
   WHERE s.name = 'B';
A: SELECT l.locktype, l.mode, l.granted
   FROM pg_locks l JOIN sessions s USING (pid)
   WHERE s.name = 'B' AND NOT l.granted;
A: COMMIT;

files.examples/02_counters.sql:
CREATE TABLE test_runs (
  id           int PRIMARY KEY,
  test_case_id int NOT NULL,
  status       text NOT NULL
);
INSERT INTO test_runs
SELECT g, g % 500, CASE WHEN g % 10 = 0 THEN 'failed' ELSE 'passed' END
FROM generate_series(1, 20000) AS g;
ANALYZE test_runs;

-- This transaction's counters for the table. pg_stat_user_tables has the same
-- columns, accumulated from every session since the last statistics reset.
CREATE VIEW counters AS
  SELECT seq_scan, seq_tup_read, idx_scan, idx_tup_fetch, n_tup_ins
  FROM pg_stat_xact_user_tables WHERE relname = 'test_runs';
SELECT * FROM counters;

-- A dashboard asks for one test case's runs. No index on test_case_id yet.
SELECT count(*) FROM test_runs WHERE test_case_id = 42;
SELECT count(*) FROM test_runs WHERE test_case_id = 43;
SELECT * FROM counters;

CREATE INDEX test_runs_case ON test_runs (test_case_id);
SELECT count(*) FROM test_runs WHERE test_case_id = 42;
SELECT count(*) FROM test_runs WHERE test_case_id = 43;
SELECT * FROM counters;

-- The shared view hasn't seen any of it yet.
SELECT seq_scan, idx_scan FROM pg_stat_user_tables WHERE relname = 'test_runs';

files.examples/03_cancel.sql:
A: INSERT INTO sessions VALUES ('A', pg_backend_pid());

-- A starts a report that runs far longer than anyone wants.
A: SELECT pg_sleep(4);
B: SELECT state, wait_event_type, wait_event, query
   FROM pg_stat_activity WHERE pid = (SELECT pid FROM sessions WHERE name = 'A');
B: SELECT pg_cancel_backend(pid) AS cancelled FROM sessions WHERE name = 'A';

-- The guard that doesn't need a human: a statement timeout.
A: SET statement_timeout = '200ms';
A: SELECT pg_sleep(1);
A: SELECT 'the session is still usable' AS status;
